from transformers import AutoTokenizer, AutoModelForCausalLM

tokenizer = AutoTokenizer.from_pretrained("Qwen/Qwen2.5-1.5B-Instruct")
model = AutoModelForCausalLM.from_pretrained("Qwen/Qwen2.5-1.5B-Instruct")

user_input = input("Введите ваш запрос: ")

messages = [
    {"role": "user", "content": f"Проектировщик. Инженер. План проекта. TODO. Составь и распиши по пунктам список план проекта (в формате Todo) для следующей задачи: «{user_input}». В него должен входить план действий, выбранный стек разработки и выбранные агенты для разработки. Также после распредели за какими задачами закреплены какие агенты. Составь последовательность действий. Пример оформления, делай строго по нему, но меняй темы, задачи и агентов: : 1. Стек технологий Для обеспечения надежности, масштабируемости и кроссплатформенности выбран следующий технологический стек:Язык программирования: TypeScript (обеспечивает строгую типизацию и снижение количества ошибок).Фреймворк интерфейса: React.js (компонентный подход, высокая производительность). Стилизация: CSS Modules / SCSS (изоляция стилей компонентов). Управление состоянием: React Context API (для хранения истории вычислений и настроек). Тестирование: Jest + React Testing Library (модульное и интеграционное тестирование). Сборка и деплой: Vite (сборка), GitHub Pages / Netlify (хостинг). Контроль версий: Git. 2. Агенты разработки Для реализации проекта определены следующие виртуальные агентские роли: Агент-Аналитик (Project Analyst): Сбор требований, формирование технического задания. Агент-Дизайнер (UI/UX Designer): Проектирование интерфейса, создание макетов. Агент-Разработчик (Frontend Engineer): Написание кода, интеграция логики и интерфейса. Агент-Тестировщик (QA Engineer): Проверка функциональности, поиск уязвимостей и ошибок 3. План проекта (TODO List Ниже представлен подробный перечень задач, необходимых для завершения проекта. Этап 1: Инициализация и проектирование 1.1. Сформулировать функциональные требования (базовые операции, история, темы). 1.2. Утвердить технический стек и среду разработки. 1.3. Разработать структуру проекта и репозитория. 1.4. Создать wireframes (схематичные макеты) интерфейса. 1.5. Утвердить финальный дизайн-макет (цвета, шрифты, отступы). Этап 2: Разработка (Implementation) 2.1. Настроить окружение разработки (инициализация React + TypeScript проекта). 2.2. Реализовать базовую логику вычислений (движок калькулятора). 2.3. Сверстать основные компоненты интерфейса (экран, кнопки, поле ввода). 2.4. Интегрировать логику вычислений с пользовательским интерфейсом. 2.5. Реализовать дополнительную функциональность (история операций, очистка). 2.6. Адаптировать интерфейс для мобильных и десктопных устройств. Этап 3: Тестирование и контроль качества3.1. Написать модульные тесты для логики вычислений.3.2. Провести ручное тестирование пользовательских сценариев.3.3. Исправить выявленные баги и недочеты.3.4. Провести проверку производительности и оптимизацию кода. Этап 4: Релиз и документация 4.1. Подготовить проект к сборке (production build). 4.2. Развернуть приложение на хостинге. 4.3. Составить инструкцию пользователя и техническую документацию. 4.4. Финальный аудит проекта. 4. Матрица распределения задач В данном разделе закреплены ответственные агенты за каждым пунктом плана. ID Задачи	 Наименование задачи Ответственный агент 1.1 Сформулировать функциональные требования Агент-Аналитик 1.2 Утвердить технический стек Агент-Аналитик 1.3 Разработать структуру проекта Агент-Разработчик 1.4 Создать wireframes интерфейса Агент-Дизайнер 1.5 Утвердить финальный дизайн-макет Агент-Дизайнер 2.1 Настроить окружение разработки Агент-Разработчик 2.2 Реализовать базовую логику вычислений Агент-Разработчик 2.3 Сверстать основные компоненты интерфейса Агент-Разработчик 2.4 Интегрировать логику с интерфейсом Агент-Разработчик 2.5 Реализовать дополнительную функциональность Агент-Разработчик 2.6 Адаптировать интерфейс (Responsive) Агент-Разработчик 3.1 Написать модульные тесты Агент-Тестировщик 3.2 Провести ручное тестирование Агент-Тестировщик 3.3 Исправить выявленные баги Агент-Разработчик 3.4 Проверка производительности Агент-Тестировщик 4.1 Подготовить проект к сборке Агент-Разработчик 4.2 Развернуть приложение на хостинге Агент-Разработчик 4.3 Составить документацию Агент-Аналитик 4.4 Финальный аудит проекта Агент-Аналитик 5. Последовательность действий (Roadmap) Реализация проекта должна осуществляться строго в следующем хронологическом порядке для минимизации рисков и переделок: Анализ: Сбор требований и утверждение стека (Задачи 1.1, 1.2). Дизайн: Проектирование визуальной части до начала написания кода (Задачи 1.4, 1.5). Настройка: Инициализация репозитория и окружения (Задачи 1.3, 2.1). Разработка ядра: Написание логики калькулятора без привязки к UI (Задача 2.2). Разработка UI: Верстка компонентов согласно макетам (Задачи 2.3, 2.6). Интеграция: Связь логики и интерфейса (Задачи 2.4, 2.5). Тестирование: Покрытие кода тестами и ручная проверка (Задачи 3.1, 3.2, 3.4). Итерация исправлений: Устранение ошибок (Задача 3.3). Деплой: Сборка и публикация (Задачи 4.1, 4.2). Документирование: Финализация сопроводительной документации (Задачи 4.3, 4.4). Документ утвержден для исполнения. "},
]
inputs = tokenizer.apply_chat_template(
	messages,
	add_generation_prompt=True,
	tokenize=True,
	return_dict=True,
	return_tensors="pt",
).to(model.device)

outputs = model.generate(**inputs, max_new_tokens=1000)
print(tokenizer.decode(outputs[0][inputs["input_ids"].shape[-1]:]))